#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────

AWS_REGION=eu-central-1
PARAMETER_PATH=/invoice-agent
# Non-secret answers only; model, Langfuse and database secrets go straight to AWS.
ENV_FILE=.env.deploy
cd "$(dirname "$0")/.."

# put_parameter NAME VALUE stores VALUE as an encrypted SSM parameter the Lambdas read.
put_parameter() {
  local file
  file=$(mktemp)
  printf '%s' "$2" > "$file"
  aws ssm put-parameter --region "$AWS_REGION" --name "$PARAMETER_PATH/$1" \
    --type SecureString --overwrite --value "file://$file" >/dev/null
  rm -f "$file"
  printf '  %s✓ stored%s %s in AWS SSM %s\n' "$GREEN" "$RESET" "$1" "$PARAMETER_PATH"
}

stack_output() {
  aws cloudformation describe-stacks --region "$AWS_REGION" \
    --stack-name invoice-agent-bootstrap \
    --query "Stacks[0].Outputs[?OutputKey=='$1'].OutputValue" --output text
}

run_wizard() {

TOTAL_STAGES=8

banner "Deploy Invoice Agent to AWS and Vercel"

stage "AWS account and CLI"
say "Create the AWS account on the Free plan, then sign the AWS CLI in as an admin."
open_url "https://signin.aws.amazon.com/signup?request_type=register"
step "Sign up and choose the Free plan."
step "Root user → Security credentials → assign an MFA device."
step "IAM Identity Center → enable → create a user with AdministratorAccess."
step "In a terminal: aws configure sso (region $AWS_REGION), and note the profile name."
warn "The Free plan ends after 6 months: upgrade to Paid with a \$20 spend limit before then."
pause "Press Enter once 'aws configure sso' has finished."
ask AWS_PROFILE "AWS CLI profile name (empty for default):"
[[ -n "$AWS_PROFILE" ]] || AWS_PROFILE=default
write_env AWS_PROFILE "$AWS_PROFILE"
export AWS_PROFILE
until aws sts get-caller-identity --query Account --output text; do
  warn "The AWS CLI is not signed in. Run: aws sso login --profile $AWS_PROFILE"
  pause "Press Enter to check again."
done
until gh auth status >/dev/null 2>&1; do
  warn "The GitHub CLI is not signed in. Run: gh auth login"
  pause "Press Enter to check again."
done

stage "Model API key"
say "The key is stored only in AWS SSM; it never reaches the browser or the repo."
ask INVOICE_MODEL_PROVIDER "Model provider (openai or anthropic):"
until [[ "$INVOICE_MODEL_PROVIDER" == openai || "$INVOICE_MODEL_PROVIDER" == anthropic ]]; do
  ask INVOICE_MODEL_PROVIDER "Type openai or anthropic:"
done
write_env INVOICE_MODEL_PROVIDER "$INVOICE_MODEL_PROVIDER"
set_var INVOICE_MODEL_PROVIDER "$INVOICE_MODEL_PROVIDER"
if [[ "$INVOICE_MODEL_PROVIDER" == openai ]]; then
  open_url "https://platform.openai.com/api-keys"
  step "Create new secret key → copy it."
  ask_secret OPENAI_API_KEY "Paste the OpenAI API key:"
  put_parameter OPENAI_API_KEY "$OPENAI_API_KEY"
else
  open_url "https://console.anthropic.com/settings/keys"
  step "Create Key → copy it."
  ask_secret ANTHROPIC_API_KEY "Paste the Anthropic API key:"
  put_parameter ANTHROPIC_API_KEY "$ANTHROPIC_API_KEY"
fi
note "Also set a monthly spend limit in the provider's billing settings."
pause

stage "Langfuse tracing (optional)"
if confirm "Trace live runs in Langfuse?"; then
  open_url "https://cloud.langfuse.com"
  step "Open the project → Settings → API Keys → Create new API keys."
  ask LANGFUSE_BASE_URL "Langfuse host (e.g. https://cloud.langfuse.com):"
  write_env LANGFUSE_BASE_URL "$LANGFUSE_BASE_URL"
  ask LANGFUSE_PUBLIC_KEY "Paste the public key (pk-lf-...):"
  ask_secret LANGFUSE_SECRET_KEY "Paste the secret key (sk-lf-...):"
  put_parameter LANGFUSE_BASE_URL "$LANGFUSE_BASE_URL"
  put_parameter LANGFUSE_PUBLIC_KEY "$LANGFUSE_PUBLIC_KEY"
  put_parameter LANGFUSE_SECRET_KEY "$LANGFUSE_SECRET_KEY"
else
  note "Skipped: live runs will have no trace link."
fi
pause

stage "Neon Postgres"
open_url "https://console.neon.tech"
step "New project → Postgres 17 → region AWS Europe Central 1 (Frankfurt)."
step "Dashboard → Connect → turn on Connection pooling → copy the connection string."
note "The pooled host contains '-pooler'; the Lambdas open many short connections."
ask_secret DATABASE_URL "Paste the pooled connection string:"
until [[ "$DATABASE_URL" == postgres* ]]; do
  ask_secret DATABASE_URL "That doesn't start with postgres. Paste it again:"
done
put_parameter DATABASE_URL "$DATABASE_URL"
pause

stage "Deploy role and image repository"
GITHUB_REPOSITORY=$(gh repo view --json nameWithOwner --jq .nameWithOwner)
say "Creates stack invoice-agent-bootstrap in $AWS_REGION: a role that only"
say "$GITHUB_REPOSITORY's main branch can assume, and the Lambda image repository."
if confirm "Deploy infra/bootstrap.yaml now?"; then
  aws cloudformation deploy --region "$AWS_REGION" \
    --template-file infra/bootstrap.yaml --stack-name invoice-agent-bootstrap \
    --capabilities CAPABILITY_IAM \
    --parameter-overrides "GitHubRepository=$GITHUB_REPOSITORY"
  set_var AWS_DEPLOY_ROLE_ARN "$(stack_output DeployRoleArn)"
  set_var AWS_IMAGE_REPOSITORY "$(stack_output ImageRepositoryUri)"
else
  SKIPPED+=("Deploy infra/bootstrap.yaml, then set AWS_DEPLOY_ROLE_ARN and AWS_IMAGE_REPOSITORY")
fi
pause

stage "Budget alert"
say "AWS emails this address when the month's spend passes, or is forecast to pass, \$5."
ask AWS_ALERT_EMAIL "Alert email:"
write_env AWS_ALERT_EMAIL "$AWS_ALERT_EMAIL"
set_var AWS_ALERT_EMAIL "$AWS_ALERT_EMAIL"
pause

stage "Vercel"
open_url "https://vercel.com/signup"
step "Sign up (Hobby plan), then come back here."
pause "Press Enter to sign the Vercel CLI in."
npx --yes vercel@65 login
say "Now link the web app. Answer the prompts like this:"
step "Set up? yes · Link to existing project? no · Name: invoice-agent"
step "Code directory: ./ · Modify settings? no · Connect a Git repository? no"
npx --yes vercel@65 link --cwd web
VERCEL_ORG_ID=$(node -p "require('./web/.vercel/project.json').orgId")
VERCEL_PROJECT_ID=$(node -p "require('./web/.vercel/project.json').projectId")
set_var VERCEL_ORG_ID "$VERCEL_ORG_ID"
set_var VERCEL_PROJECT_ID "$VERCEL_PROJECT_ID"
open_url "https://vercel.com/account/settings/tokens"
step "Create Token → scope: your team → copy it."
ask_secret VERCEL_TOKEN "Paste the Vercel token:"
set_secret VERCEL_TOKEN "$VERCEL_TOKEN"
step "Project invoice-agent → Settings → Domains: the production domain."
note "Usually https://invoice-agent.vercel.app, with a suffix if that name was taken."
ask WEB_URL "Production URL (https://...):"
write_env WEB_URL "${WEB_URL%/}"
set_var WEB_URL "$WEB_URL"

stage "First deploy"
say "Every push to main now runs the checks, deploys AWS and Vercel, and"
say "uploads an Invoice on $WEB_URL as a smoke check."
step "Push main (git push origin main) and watch the Checks workflow."
open_url "https://github.com/$GITHUB_REPOSITORY/actions"
pause

finish
}

run_wizard "$@"; exit
